/* TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Authors: Jack; Brendon (integrator) renamed the playback state type for the PD6 port (Sep 2026) and
 *          added playback_start_at (29-30 Oct 2026, best-ui), with an AI coding assistant. */
/* The bookkeeping of one playback: it reads the samples of the open WAV
 * file (its data chunk) in chunks, never past the data size the header
 * gives, and says when the end (EOF) or a read fault is reached. See
 * playback_session.h for the states and the requirement numbers.
 *
 * No task of its own: jack_audio_sd.c calls it inside JackStorageTask.
 *   1. playback_start_at() when a play starts, also part-way in (a resume or
 *      an effect switch); playback_start() when the loop goes back to the
 *      first sample;
 *   2. playback_read_chunk() each time the 4 KB read buffer is used up:
 *      Storage_ReadChunk (jack_ports.c: f_read) for at most the bytes left;
 *      EOF once all of them are read; FAULT on a failed read (sticky);
 *   3. playback_stop() on a stop, a pause or an effect switch.
 * Pure logic, no RTOS or HAL (tests: Tests/test_playback_session.c). */
#include "playback_session.h"

void playback_start(playback_session_t *session, uint32_t total_data_size)
{
    if (session == NULL)
    {
        return;
    }
    session->state = JACK_PLAYBACK_PLAYING;
    session->bytes_read = 0U;
    session->total_data_size = total_data_size;
    session->last_fault = STORAGE_OK;
}

/* TEAM CODE (written by Brendon, integrator, 29-30 Oct 2026, best-ui): playback_start_at() */
void playback_start_at(playback_session_t *session, uint32_t total_data_size, uint32_t offset)
{
    if (session == NULL)
    {
        return;
    }
    playback_start(session, total_data_size);
    uint32_t start = (offset > total_data_size) ? total_data_size : offset;
    start -= (start % 2U);                      /* whole 16-bit samples only */
    session->bytes_read = start;                /* as if those bytes had been read */
}

storage_result_t playback_read_chunk(playback_session_t *session,
                                      uint8_t *out,
                                      size_t max_len,
                                      size_t *out_len)
{
    if ((session == NULL) || (out == NULL) || (out_len == NULL) || (max_len == 0U))
    {
        return STORAGE_INVALID_ARG;
    }

    *out_len = 0U;

    if (session->state == JACK_PLAYBACK_EOF)
    {
        /* Repeated calls after EOF remain deterministic - always 0 bytes,
         * no further hardware access. */
        return STORAGE_OK;
    }

    if (session->state != JACK_PLAYBACK_PLAYING)
    {
        return STORAGE_INVALID_ARG;
    }

    const uint32_t remaining = session->total_data_size - session->bytes_read;
    if (remaining == 0U)
    {
        session->state = JACK_PLAYBACK_EOF;
        return STORAGE_OK;
    }

    /* Never ask the storage layer for more than the file actually
     * contains, even if the caller's buffer is bigger. */
    size_t request_len = max_len;
    if ((uint32_t)request_len > remaining)
    {
        request_len = (size_t)remaining;
    }

    size_t actually_read = 0U;
    const storage_result_t result = Storage_ReadChunk(out, request_len, &actually_read);

    if (result != STORAGE_OK)
    {
        session->state = JACK_PLAYBACK_FAULT;
        session->last_fault = result;
        return result;
    }

    session->bytes_read += (uint32_t)actually_read;
    *out_len = actually_read;

    if (session->bytes_read >= session->total_data_size)
    {
        session->state = JACK_PLAYBACK_EOF;
    }

    return STORAGE_OK;
}

void playback_stop(playback_session_t *session)
{
    if (session == NULL)
    {
        return;
    }
    if ((session->state == JACK_PLAYBACK_PLAYING) || (session->state == JACK_PLAYBACK_EOF))
    {
        session->state = JACK_PLAYBACK_IDLE;
    }
}
